import{_ as t,o as s,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse(`{"title":"ATLAS","description":"Présentation du framework ATLAS et de son application pour Home Assistant.","frontmatter":{"layout":"home","title":"ATLAS","description":"Présentation du framework ATLAS et de son application pour Home Assistant.","hero":{"name":"ATLAS","text":"Framework d'applications modulaire","tagline":"Un framework TypeScript modulaire pour créer des applications réutilisables, des plugins et des outils liés à Home Assistant.","actions":[{"theme":"brand","text":"Architecture","link":"/fr/projects/atlas/overview"},{"theme":"alt","text":"État du développement","link":"/fr/projects/atlas/development-status"},{"theme":"alt","text":"Home Assistant","link":"/fr/projects/atlas/homeassistant"},{"theme":"alt","text":"Plugins ATLAS","link":"/fr/projects/atlas-plugins/"}]},"features":[{"icon":"modules","title":"Architecture modulaire","details":"Séparation claire entre Core, Foundation, Runtime, Renderer, Home Assistant, Theme et Devtools."},{"icon":"gear","title":"Fondations Runtime","details":"Services, injection de dépendances, événements et autres éléments essentiels de l'exécution."},{"icon":"plugin","title":"Extensible par plugins","details":"ATLAS fournit la plateforme et une documentation dédiée aux auteurs de plugins."},{"icon":"home","title":"Intégration Home Assistant","details":"Les panneaux d'état, la sélection d'entités, l'export de cartes et la vérification des ressources Lovelace évoluent progressivement."},{"icon":"test","title":"Testable","details":"Des contrats clairs, des implémentations de référence et des tests automatisés en constituent la base."},{"icon":"package","title":"Monorepo","details":"Les paquets sont gérés avec les espaces de travail pnpm et des responsabilités distinctes."}]},"headers":[],"relativePath":"fr/projects/atlas/index.md","filePath":"fr/projects/atlas/index.md","lastUpdated":1793118610000}`),a={name:"fr/projects/atlas/index.md"};function r(o,e,l,d,p,u){return s(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="etat-du-projet" tabindex="-1">État du projet <a class="header-anchor" href="#etat-du-projet" aria-label="Permalink to &quot;État du projet&quot;">​</a></h2><p>ATLAS est en cours de développement. L&#39;effort porte actuellement sur l&#39;application ATLAS pour Home Assistant, qui comprend l&#39;Administration, le Hub des plugins, Card Editor et File Studio.</p><p>Au 17/10/2026 : <strong>App 0.1.315</strong>, <strong>intégration HACS 0.1.306</strong>. Card Editor est le seul plugin de référence intégré. File Studio, Terminal, Icon Studio, Icon Library et Automation Exporter / Editor sont maintenus séparément comme plugins externes. Consulter l’<a href="./development-status">état du développement</a> pour le périmètre vérifié et les tâches ouvertes.</p><p>L&#39;Administration et le Hub des plugins prennent en charge l&#39;allemand, l&#39;anglais et le français. Le choix de langue est mémorisé et partagé entre les deux interfaces, même lorsqu&#39;elles utilisent des ports d&#39;application différents. Un paramètre de langue présent dans l&#39;URL d&#39;un plugin reste prioritaire.</p><div class="warning custom-block"><p class="custom-block-title">Projet en développement</p><p>ATLAS n&#39;est pas encore déclaré prêt pour un usage en production. Les API, les structures de paquets et les contrats internes peuvent encore évoluer.</p></div><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>ATLAS vise à fournir une base technique commune à plusieurs projets UGSo :</p><ul><li>services réutilisables, EventBus et injection de dépendances ;</li><li>plugins modulaires et outils de diagnostic et de développement ;</li><li>intégrations Home Assistant, Administration et Hub des plugins ;</li><li>File Studio pour les chemins Home Assistant autorisés ;</li><li>Card Editor avec un flux Expert direct ;</li><li>structures communes de thèmes et de rendu.</li></ul>',8)])])}const A=t(a,[["render",r]]);export{m as __pageData,A as default};
